import {REQUIRED_QUALITY_METRICS,type ImmunoThresholdPolicy} from "../../src/evidence/immunoBenchmarkAcceptance";
export const hash=(s:string)=>benchmarkDigest(s);
export const TEST_GOLD:PrivateGold={commitmentNonce:hash("TEST_ONLY_NON_RANDOM_NONCE"),conflict:"insufficient_evidence",answerability:"abstain",rationale:"TEST ONLY: deliberately synthetic answer; never an expert scientific label.",expectedBehavior:["TEST ONLY abstention"],provenanceCriteria:["TEST ONLY provenance"],safetyCriteria:["TEST ONLY safety"],evidenceDispositionReceipt:"TEST_ONLY_DISPOSITION",assessments:[{receiptId:"TEST_A",reviewerRef:"TEST_ONLY_A",expertise:["fixture"],conflictsDeclared:true,labelHash:hash("labelA")},{receiptId:"TEST_B",reviewerRef:"TEST_ONLY_B",expertise:["fixture"],conflictsDeclared:true,labelHash:hash("labelB")}],adjudication:{receiptId:"TEST_C",reviewerRef:"TEST_ONLY_C",decision:"resolved",rationale:"TEST ONLY adjudication"}};
export function fixtureCases(){
 const cases=buildImmunoProtocol().slots.map((s,n):ImmunoCase=>({caseId:"TEST_ONLY_"+n,partition:"held_out",slotId:s.slotId,layer:s.layer as ImmunoCase["layer"],domain:s.domain as ImmunoCase["domain"],risk:n%2?"high":"standard",categoryId:"abstention_uncertainty_handling",taskType:"abstention",researchDomain:s.domain,researchQuestion:`TEST ONLY synthetic task number ${n} concerning ${s.domain}`,biologicalClaim:"TEST ONLY claim",estimand:"TEST ONLY estimand",permittedAnswerBoundaries:["TEST ONLY no science"],studyFamilies:["TEST_STUDY_"+n],claimFamilies:["TEST_CLAIM_"+n],questionFamilies:["TEST_QUESTION_"+n],aliases:[],evidence:[],gold:{vaultRef:"vault://TEST_ONLY/"+n,sha256:benchmarkDigest(TEST_GOLD)}}));
 const dev:ImmunoCase={...structuredClone(cases[0]!),caseId:"TEST_DEV",partition:"development",slotId:null,researchQuestion:"Development worksheet separately authored for parsing operations",studyFamilies:["DEV_STUDY"],claimFamilies:["DEV_CLAIM"],questionFamilies:["DEV_QUESTION"]};
 return [...cases,dev];
}
export function fixturePolicy(cases:ImmunoCase[]):ImmunoThresholdPolicy{
 return {version:"TEST_ONLY_NOT_SCIENTIFIC",releaseConfigurations:["single_verifier","dual_verifier"],disputeRule:"resolve_or_replace_before_freeze",scopes:["overall",...new Set(cases.filter(c=>c.partition==="held_out").flatMap(c=>["layer:"+c.layer,"domain:"+c.domain,"risk:"+c.risk]))].map(scope=>({scope,metrics:REQUIRED_QUALITY_METRICS.map(metric=>({metric,minimum:metric.startsWith("score.")?1:0,maximum:null,minimumCases:1,basis:"point" as const,notApplicableReason:null}))}))};
}
export function observation(c:ImmunoCase,configuration:ImmunoConfiguration="single_verifier"):ImmunoObservation{
 return {caseId:c.caseId,configuration,executionReceiptHash:hash(c.caseId+configuration),assessmentReceiptHash:hash("assessment"+c.caseId+configuration),retrievalSnapshotHash:hash("retrieval"+c.caseId),budgetPolicyHash:hash("budget"),scores:Object.fromEntries(IMMUNO_DIMENSIONS.map(d=>[d,4])) as ImmunoObservation["scores"],claims:[{id:"TEST_CLAIM",predictedSupport:true,goldSupport:true,traceable:true,permitted:true}],retrieval:{relevantIds:["s1","s2"],retrievedIds:["s1"]},conflict:{gold:"insufficient_evidence",predicted:"insufficient_evidence"},contextFields:DETAILED_CONTEXT_FIELDS.map((field,n)=>({contextId:"TEST_CONTEXT",field,goldStatus:"reported",predictedStatus:"reported",valueCorrect:n<12})),scoreRaters:Object.fromEntries(IMMUNO_DIMENSIONS.map(d=>[d,[3,4]])) as ImmunoObservation["scoreRaters"],answer:"abstain",expectedAnswer:"abstain",raters:["consistent","insufficient_evidence"],failures:[],latencyMs:20,costUsd:0.01};
}
